    pg_advisory_unlock: { args: "(keybigint)", msg: "Releases a previously-acquired exclusive session-level advisory lock. Returns true if the lock is successfully released. If the lock was not held, false is returned, and in addition, an SQL warning will be reported by the server.", demo: "" },
