// src/service/main/dialect/postgres/gaussDBDialect.ts
var Pv = class extends Ad {
  showVersion() {
    return "SELECT VERSION() as server_version";
  }
  createIndex(e) {
    return null;
  }
  variableList() {
    return "SHOW ALL";
  }
  statusList() {
    return `SELECT
        'db_numbackends' AS db,
        pg_stat_get_db_numbackends(datid) AS status
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_xact_commit',
        pg_stat_get_db_xact_commit(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_xact_rollback',
        pg_stat_get_db_xact_rollback(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_blocks_fetched',
        pg_stat_get_db_blocks_fetched(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()
      UNION ALL
      SELECT
        'db_blocks_hit',
        pg_stat_get_db_blocks_hit(datid)
      FROM
        pg_stat_database
      WHERE
        datname = current_database()`;
  }
  processList() {
    return `SELECT
        a.pid AS "Id",
        a.usename AS "User",
        a.client_addr AS "Host",
        a.client_port AS "Port",
        datname AS "db",
        query AS "Command",
        l.mode AS "State",
        query_start AS "Time",
        CASE
          WHEN c.relname IS NOT NULL THEN 'Locked Object: ' || c.relname
          ELSE 'Locked Transaction: ' || l.virtualtransaction
        END AS "Info"
      FROM
        pg_stat_activity a
        LEFT JOIN pg_locks l ON a.pid = l.pid
        LEFT JOIN pg_class c ON l.relation = c.oid
      ORDER BY
        a.pid ASC,
        c.relname ASC`;
  }
  addColumn(e, t) {
    return `ALTER TABLE ${e}
  ADD COLUMN [column] [type];
COMMENT ON COLUMN ${e}.[column] IS 'comment';`;
  }
  createUser() {
    return "CREATE USER [name] WITH PASSWORD 'password';";
  }
  updateUser(e) {
    return `ALTER USER ${e} WITH PASSWORD 'new_password';`;
  }
  updateColumn(e, t) {
    let { name: n, type: s } = t;
    return `-- change column type
ALTER TABLE ${e}
    ALTER COLUMN ${n} TYPE ${s};
-- change column name
ALTER TABLE ${e}
    RENAME COLUMN ${n} TO ${n};`;
  }
  /**
   * Redshift的自增为: "identity"(110415, 0, '1,1'::text), 但由于其不允许修改默认值, 所以目前没影响
   */
  updateColumnSql(e) {
    return new jm(e).genAlterSQL();
  }
  showUsers() {
    return 'SELECT usename "user" from pg_user ';
  }
  updateTable(e) {
    let { table: t, newTableName: n, comment: s, newComment: o } = e, a = "";
    return o && o != s && (a = `COMMENT ON TABLE "${t}" IS '${o}';`), n && t != n && (a += `ALTER TABLE "${t}" RENAME TO "${n}";`), a;
  }
  truncateDatabase(e) {
    return `SELECT Concat('TRUNCATE TABLE "',TABLE_NAME, '";') trun FROM INFORMATION_SCHEMA.TABLES WHERE  table_schema ='${e}' AND table_type='BASE TABLE';`;
  }
  createDatabase(e) {
    return "CREATE DATABASE $1";
  }
  showTableSource(e, t) {
    return `SELECT pg_get_tabledef('${e}.${t}');`;
  }
  showViewSource(e, t, n) {
    return n ? `SELECT CONCAT('CREATE MATERIALIZED VIEW ',matviewname,'
AS
(',regexp_replace(definition,';$',''),')') "Create View"
    ,matviewname "table_name",'definition' "view_definition" from pg_matviews
    WHERE schemaname='${e}' and matviewname='${t}';` : `SELECT CONCAT('CREATE VIEW ',table_name,'
AS
(',regexp_replace(view_definition,';$',''),')') "Create View"
    ,table_name,view_definition from information_schema.views 
    where table_schema='${e}' and table_name='${t}'`;
  }
  showMaterialViewSource(e, t) {
    return `SELECT CONCAT('CREATE MATERIALIZED VIEW ',matviewname,'
AS
(',regexp_replace(definition,';$',''),')') "Create View"
    ,matviewname "table_name",'definition' "view_definition" from pg_matviews
    WHERE schemaname='${e}' and matviewname='${t}';`;
  }
  showProcedureSource(e, t) {
    return `select pg_get_functiondef('${e}.${t}' :: regproc) "Create Procedure",'${t}' "Procedure";`;
  }
  showFunctionSource(e, t) {
    return `select pg_get_functiondef('${e}.${t}' :: regproc) "Create Function",'${t}' "Function";`;
  }
  showTriggerSource(e, t) {
    return `select pg_get_triggerdef(oid) "SQL Original Statement",'${e}.${t}' "Trigger" from pg_trigger where tgname = '${t}';`;
  }
  showPartitions(e, t) {
    return "";
  }
  showSequences(e) {
    return `SELECT sequence_name name FROM information_schema.sequences WHERE sequence_schema = '${e}' ORDER BY sequence_name`;
  }
  showTriggers(e, t) {
    let n = t ? ` AND event_object_table='${t}'` : "";
    return `SELECT TRIGGER_NAME "trigger_name" FROM information_schema.TRIGGERS WHERE trigger_schema = '${e}' ${n} ORDER BY TRIGGER_NAME ASC`;
  }
  showProcedures(e) {
    return ` SELECT proname AS "ROUTINE_NAME",
       pg_catalog.pg_get_function_arguments(p.oid) AS "argDefs"
FROM pg_catalog.pg_proc p
     LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
WHERE pg_catalog.pg_function_is_visible(p.oid)
  AND n.nspname = '${e}'
  AND p.prokind = 'p'; `;
  }
  showFunctions(e) {
    return `SELECT proname AS name,
       pg_catalog.pg_get_function_result(p.oid) AS return_type,
       pg_catalog.pg_get_function_arguments(p.oid) AS "argDefs",
       CASE
           WHEN p.proisagg THEN 'agg'
           WHEN p.proiswindow THEN 'window'
           WHEN p.prorettype = 'pg_catalog.trigger'::pg_catalog.regtype THEN 'trigger'
           ELSE 'normal'
       END AS type
FROM pg_catalog.pg_proc p
     LEFT JOIN pg_catalog.pg_namespace n ON n.oid = p.pronamespace
WHERE pg_catalog.pg_function_is_visible(p.oid)
  AND n.nspname = '${e}'
  AND p.prokind = 'f';  `;
  }
  showTables(e, t) {
    return `SELECT t.table_name "name", pg_catalog.obj_description(pgc.oid, 'pg_class') "comment",
    pg_total_relation_size(quote_ident(table_name)) AS "data_length"
FROM information_schema.tables t
JOIN pg_catalog.pg_class pgc ON t.table_name = pgc.relname
JOIN pg_catalog.pg_namespace pgn ON pgn.oid=pgc.relnamespace and pgn.nspname=t.table_schema
WHERE t.table_type='BASE TABLE'
AND t.table_schema='${t}' order by t.table_name;`;
  }
  showSchemas() {
    return 'SELECT nspname "schema" from pg_catalog.pg_namespace order by nspname ASC;';
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(  
    id serial NOT NULL PRIMARY KEY,
    create_time DATE,
    name$2 VARCHAR(255)
);
COMMENT ON TABLE table_name$1 IS '$3';
COMMENT ON COLUMN table_name$1.name$2 IS '$4';`;
  }
  procedureTemplate() {
    return `CREATE OR REPLACE PROCEDURE procedure_name()
AS
BEGIN
   SELECT 1;
END;`;
  }
  functionTemplate() {
    return `CREATE FUNCTION function_name()
RETURNS int STABLE
AS $$
    SELECT 1
$$ LANGUAGE sql;`;
  }
};

// src/service/main/dialect/sql-other/databricksDialect.ts
var Mv = class extends wo {
  showVersion() {
    return "select version() as server_version;";
  }
  showDatabases() {
    return "SHOW CATALOGS";
  }
  pingDataBase(e, t) {
    return `USE ${e}`;
  }
  showTables(e, t) {
    return `SELECT table_name FROM information_schema.tables
   WHERE table_catalog = '${e}' and table_schema = '${t}' and TABLE_TYPE<>'VIEW' `;
  }
  tableTemplate() {
    return `CREATE TABLE table_name$1(
    id LONG PRIMARY KEY,
    create_time DATE,
    update_time DATE,
    content STRING
);`;
  }
  showColumns(e, t) {
    return `SELECT c.COLUMN_NAME name,
c.DATA_TYPE type, c.IS_NULLABLE nullable,
CASE WHEN tc.constraint_type = 'PRIMARY KEY' THEN 'YES' ELSE 'NO' END AS key
    FROM information_schema.columns c
    LEFT JOIN 
        information_schema.key_column_usage kcu ON c.table_schema = kcu.table_schema
        AND c.table_name = kcu.table_name AND c.column_name = kcu.column_name
    LEFT JOIN 
        information_schema.table_constraints tc ON kcu.constraint_name = tc.constraint_name
        AND kcu.table_schema = tc.table_schema AND kcu.table_name = tc.table_name
    WHERE c.table_schema = '${e}' AND c.table_name = '${t}'
    ORDER BY c.ordinal_position;`;
  }
  createDatabase(e) {
    return `CREATE CATALOG $1${e};`;
  }
  dropDatabase(e) {
    return `DROP CATALOG ${e};`;
  }
};

