// src/bin/sql-formatter/languages/mariadb/likeMariaDb.ts
function FS(r) {
  return r.map((e, t) => {
    let n = r[t + 1] || wd;
    if (Nf.SET(e) && n.text === "(")
      return { ...e, type: "RESERVED_FUNCTION_NAME" };
    let s = r[t - 1] || wd;
    return Nf.VALUES(e) && s.text === "=" ? { ...e, type: "RESERVED_FUNCTION_NAME" } : e;
  });
}

